// Error hierarchy mirroring PyYAML's error module.

export class Mark {
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && !isBreakOrZero(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ...';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && !isBreakOrZero(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ...';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end);
    const pad = ' '.repeat(indent);
    const caretPad = ' '.repeat(indent + this.pointer - start + head.length);
    return pad + head + snippet + tail + '\n' + caretPad + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

function isBreakOrZero(ch) {
  return ch === '\0' || ch === '\r' || ch === '\n' || ch === '\x85' ||
    ch === ' ' || ch === ' ';
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(problem || context || 'error');
    this.name = 'MarkedYAMLError';
    this.context = context ?? null;
    this.contextMark = contextMark ?? null;
    this.problem = problem ?? null;
    this.problemMark = problemMark ?? null;
    this.note = note ?? null;
  }

  toString() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (this.contextMark !== null &&
      (this.problem === null || this.problemMark === null ||
        this.contextMark.name !== this.problemMark.name ||
        this.contextMark.line !== this.problemMark.line ||
        this.contextMark.column !== this.problemMark.column)) {
      lines.push(this.contextMark.toString());
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(this.problemMark.toString());
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }
}

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super(reason);
    this.name = 'ReaderError';
    this.streamName = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
  }

  toString() {
    return `unacceptable character #x${hex(this.character)}: ${this.reason}\n` +
      `  in "${this.streamName}", position ${this.position}`;
  }
}

function hex(ch) {
  const cp = typeof ch === 'number' ? ch : ch.codePointAt(0);
  let s = cp.toString(16);
  if (s.length < 4) s = '0'.repeat(4 - s.length) + s;
  return s;
}

export class ScannerError extends MarkedYAMLError {
  constructor(...args) {
    super(...args);
    this.name = 'ScannerError';
  }
}

export class ParserError extends MarkedYAMLError {
  constructor(...args) {
    super(...args);
    this.name = 'ParserError';
  }
}

export class ComposerError extends MarkedYAMLError {
  constructor(...args) {
    super(...args);
    this.name = 'ComposerError';
  }
}

export class ConstructorError extends MarkedYAMLError {
  constructor(...args) {
    super(...args);
    this.name = 'ConstructorError';
  }
}

export class EmitterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'EmitterError';
  }
}

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'SerializerError';
  }
}

export class RepresenterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'RepresenterError';
  }
}

