// Character classification helpers.
//
// Everything here is table/comparison driven -- no pattern-matching engine is
// used anywhere in this project.

/** Membership test against a literal set of single characters. */
export function inChars(ch, chars) {
  if (ch === null || ch === undefined || ch === '') return false;
  return chars.indexOf(ch) !== -1;
}

export const LINEBR_ALL = '\n\r\x85  ';

export function isLineBreak(ch) {
  return ch === '\n' || ch === '\r' || ch === '\x85' ||
    ch === ' ' || ch === ' ';
}

/** Line breaks as recognised by the scalar analyser (\r excluded). */
export function isBreakChar(ch) {
  return ch === '\n' || ch === '\x85' || ch === ' ' || ch === ' ';
}

export function isSpaceOrTab(ch) {
  return ch === ' ' || ch === '\t';
}

/** '\0', space, tab or any line break -- PyYAML's '\0 \t\r\n\x85  '. */
export function isWhitespaceZ(ch) {
  return ch === '\0' || ch === ' ' || ch === '\t' || isLineBreak(ch);
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') ||
    (ch >= 'A' && ch <= 'F');
}

export function isOctDigit(ch) {
  return ch >= '0' && ch <= '7';
}

export function isAlpha(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_';
}

export function digitValue(ch) {
  return ch.charCodeAt(0) - 48;
}

export function hexValue(ch) {
  const c = ch.charCodeAt(0);
  if (c >= 48 && c <= 57) return c - 48;
  if (c >= 97 && c <= 102) return c - 87;
  return c - 55;
}

/** Decompose a string into an array of Unicode code points (Python `str`). */
export function toCodePoints(str) {
  const out = [];
  for (const ch of str) out.push(ch);
  return out;
}

/** Pad a non-negative integer with leading zeros. */
export function zfill(value, width) {
  let s = String(value);
  while (s.length < width) s = '0' + s;
  return s;
}

