// A small model of the Python runtime values that PyYAML's safe loader can
// produce, plus the pieces of Python semantics the dumper depends on.
//
// Mapping of Python types onto JavaScript:
//   None      -> null
//   bool      -> boolean
//   int       -> BigInt          (arbitrary precision, like Python)
//   float     -> number          (IEEE-754 double, like Python)
//   str       -> string
//   bytes     -> Uint8Array
//   list      -> Array
//   tuple     -> PyTuple
//   dict      -> PyDict          (insertion ordered, Python key equality)
//   set       -> PySet
//   date      -> PyDate
//   datetime  -> PyDateTime

import { zfill } from './chars.mjs';

/** Raised where CPython would raise TypeError. */
export class PyTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TypeError';
  }
}

/** Raised where CPython would raise ValueError. */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export function isBytes(v) {
  return v instanceof Uint8Array;
}

// ---------------------------------------------------------------------------
// Key identity
// ---------------------------------------------------------------------------

let nanCounter = 0;

/**
 * Canonical key string reproducing Python's `==`/`hash` behaviour for the
 * hashable types safe_load can build.  In Python `True == 1 == 1.0`, so all
 * three have to collapse onto one slot.
 */
export function keyId(key) {
  if (key === null) return 'n';
  if (typeof key === 'boolean') return 'i' + (key ? '1' : '0');
  if (typeof key === 'bigint') return 'i' + key.toString();
  if (typeof key === 'number') {
    if (Number.isNaN(key)) return 'x' + (nanCounter++);
    if (key === Infinity) return 'f+inf';
    if (key === -Infinity) return 'f-inf';
    if (Number.isInteger(key)) return 'i' + BigInt(key).toString();
    return 'f' + key;
  }
  if (typeof key === 'string') return 's' + key;
  if (isBytes(key)) return 'b' + Array.from(key).join(',');
  if (key instanceof PyTuple) {
    return 't(' + key.items.map(keyId).join('') + ')';
  }
  if (key instanceof PyDate) return 'd' + key.isoformat();
  return 'o' + objectId(key);
}

const idMap = new WeakMap();
let idCounter = 0;

/** Stand-in for CPython's `id()`, used for alias detection. */
export function objectId(obj) {
  if (obj === null || (typeof obj !== 'object' && typeof obj !== 'function')) {
    return 'v' + String(obj);
  }
  let id = idMap.get(obj);
  if (id === undefined) {
    id = 'o' + (idCounter++);
    idMap.set(obj, id);
  }
  return id;
}

export class PyDict {
  constructor() {
    this.map = new Map(); // keyId -> [key, value]
  }

  get size() {
    return this.map.size;
  }

  set(key, value) {
    const id = keyId(key);
    const existing = this.map.get(id);
    // Python keeps the *first* key object but the last value.
    if (existing !== undefined) existing[1] = value;
    else this.map.set(id, [key, value]);
  }

  has(key) {
    return this.map.has(keyId(key));
  }

  get(key) {
    const e = this.map.get(keyId(key));
    return e === undefined ? undefined : e[1];
  }

  /** Entries in insertion order, as [key, value] pairs. */
  items() {
    return Array.from(this.map.values(), (e) => [e[0], e[1]]);
  }

  keys() {
    return Array.from(this.map.values(), (e) => e[0]);
  }

  /** dict.update(other) -- other's entries win, insertion order preserved. */
  update(other) {
    for (const [k, v] of other.items()) this.set(k, v);
  }
}

export class PySet {
  constructor() {
    this.map = new Map(); // keyId -> key
  }

  get size() {
    return this.map.size;
  }

  add(key) {
    const id = keyId(key);
    if (!this.map.has(id)) this.map.set(id, key);
  }

  values() {
    return Array.from(this.map.values());
  }
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeap(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

export function daysInMonth(year, month) {
  if (month === 2 && isLeap(year)) return 29;
  return DAYS_IN_MONTH[month - 1];
}

export class PyDate {
  constructor(year, month, day) {
    if (year < 1 || year > 9999) {
      throw new PyValueError(`year ${year} is out of range`);
    }
    if (month < 1 || month > 12) {
      throw new PyValueError('month must be in 1..12');
    }
    const limit = daysInMonth(year, month);
    if (day < 1 || day > limit) {
      throw new PyValueError(`day is out of range for month`);
    }
    this.year = year;
    this.month = month;
    this.day = day;
  }

  isoformat() {
    return `${zfill(this.year, 4)}-${zfill(this.month, 2)}-${zfill(this.day, 2)}`;
  }
}

export class PyDateTime extends PyDate {
  constructor(year, month, day, hour, minute, second, microsecond, tzOffsetMinutes) {
    super(year, month, day);
    if (hour < 0 || hour > 23) throw new PyValueError('hour must be in 0..23');
    if (minute < 0 || minute > 59) throw new PyValueError('minute must be in 0..59');
    if (second < 0 || second > 59) throw new PyValueError('second must be in 0..59');
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    // null means a naive datetime.
    this.tzOffsetMinutes = tzOffsetMinutes === undefined ? null : tzOffsetMinutes;
  }

  isoformat(sep = 'T') {
    let s = `${zfill(this.year, 4)}-${zfill(this.month, 2)}-${zfill(this.day, 2)}` +
      sep +
      `${zfill(this.hour, 2)}:${zfill(this.minute, 2)}:${zfill(this.second, 2)}`;
    if (this.microsecond) s += '.' + zfill(this.microsecond, 6);
    if (this.tzOffsetMinutes !== null) {
      const total = this.tzOffsetMinutes;
      const sign = total < 0 ? '-' : '+';
      const abs = Math.abs(total);
      s += `${sign}${zfill(Math.floor(abs / 60), 2)}:${zfill(abs % 60, 2)}`;
    }
    return s;
  }
}

// ---------------------------------------------------------------------------
// repr()
// ---------------------------------------------------------------------------

/**
 * CPython's `repr()` for floats: the shortest digit string that round-trips,
 * switching to exponential notation when decpt <= -4 or decpt > 16.
 */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  const negative = value < 0 || Object.is(value, -0);
  const abs = Math.abs(value);
  if (abs === 0) return negative ? '-0.0' : '0.0';

  // `toExponential()` with no argument yields the shortest round-tripping
  // digit string, which is exactly what CPython's repr is built from.
  const text = abs.toExponential();
  let digits = '';
  let exponent = 0;
  let i = 0;
  for (; i < text.length; i++) {
    const ch = text[i];
    if (ch === 'e') break;
    if (ch !== '.') digits += ch;
  }
  i++; // skip 'e'
  let expSign = 1;
  if (text[i] === '+') i++;
  else if (text[i] === '-') { expSign = -1; i++; }
  for (; i < text.length; i++) exponent = exponent * 10 + (text.charCodeAt(i) - 48);
  exponent *= expSign;

  // Strip trailing zeros of the digit string (CPython works with the shortest
  // significant-digit form).
  let end = digits.length;
  while (end > 1 && digits[end - 1] === '0') end--;
  digits = digits.slice(0, end);

  const decpt = exponent + 1; // value === 0.<digits> * 10**decpt
  let body;
  if (decpt <= -4 || decpt > 16) {
    body = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const e = decpt - 1;
    body += 'e' + (e < 0 ? '-' : '+') + zfill(Math.abs(e), 2);
  } else if (decpt <= 0) {
    body = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    body = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return negative ? '-' + body : body;
}

// ---------------------------------------------------------------------------
// Ordering
// ---------------------------------------------------------------------------

const NUMBER = 1;
const STRING = 2;
const BYTES = 3;
const TUPLE = 4;
const DATE = 5;
const DATETIME = 6;
const OTHER = 0;

function orderClass(v) {
  if (typeof v === 'boolean' || typeof v === 'bigint' || typeof v === 'number') return NUMBER;
  if (typeof v === 'string') return STRING;
  if (isBytes(v)) return BYTES;
  if (v instanceof PyTuple) return TUPLE;
  if (v instanceof PyDateTime) return DATETIME;
  if (v instanceof PyDate) return DATE;
  return OTHER;
}

function typeName(v) {
  if (v === null) return 'NoneType';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'number') return 'float';
  if (typeof v === 'string') return 'str';
  if (isBytes(v)) return 'bytes';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDateTime) return 'datetime.datetime';
  if (v instanceof PyDate) return 'datetime.date';
  if (v instanceof PyDict) return 'dict';
  if (v instanceof PySet) return 'set';
  if (Array.isArray(v)) return 'list';
  return 'object';
}

function numeric(v) {
  if (typeof v === 'boolean') return v ? 1 : 0;
  if (typeof v === 'bigint') return v;
  return v;
}

function compareNumbers(a, b) {
  const x = numeric(a);
  const y = numeric(b);
  if (typeof x === 'bigint' && typeof y === 'bigint') {
    return x < y ? -1 : x > y ? 1 : 0;
  }
  // Mixed int/float: compare exactly where it matters by promoting the float.
  let xv = x;
  let yv = y;
  if (typeof xv === 'bigint') {
    if (Number.isNaN(yv)) return NaN;
    if (yv === Infinity) return -1;
    if (yv === -Infinity) return 1;
    if (Number.isInteger(yv)) { yv = BigInt(yv); return xv < yv ? -1 : xv > yv ? 1 : 0; }
    const xf = Number(xv);
    return xf < yv ? -1 : xf > yv ? 1 : 0;
  }
  if (typeof yv === 'bigint') {
    if (Number.isNaN(xv)) return NaN;
    if (xv === Infinity) return 1;
    if (xv === -Infinity) return -1;
    if (Number.isInteger(xv)) { xv = BigInt(xv); return xv < yv ? -1 : xv > yv ? 1 : 0; }
    const yf = Number(yv);
    return xv < yf ? -1 : xv > yf ? 1 : 0;
  }
  if (Number.isNaN(xv) || Number.isNaN(yv)) return NaN;
  return xv < yv ? -1 : xv > yv ? 1 : 0;
}

function dateTuple(v) {
  const base = [v.year, v.month, v.day];
  if (v instanceof PyDateTime) {
    base.push(v.hour, v.minute, v.second, v.microsecond);
  }
  return base;
}

/**
 * Three-way comparison following CPython's rules; throws PyTypeError for
 * unorderable pairs, exactly where Python's `<` would.
 */
export function pyCompare(a, b) {
  const ca = orderClass(a);
  const cb = orderClass(b);
  if (ca === OTHER || cb === OTHER || ca !== cb) {
    throw new PyTypeError(
      `'<' not supported between instances of '${typeName(a)}' and '${typeName(b)}'`);
  }
  switch (ca) {
    case NUMBER: {
      const r = compareNumbers(a, b);
      return Number.isNaN(r) ? 0 : r;
    }
    case STRING: {
      // Python compares str by code point.
      const x = Array.from(a);
      const y = Array.from(b);
      const n = Math.min(x.length, y.length);
      for (let i = 0; i < n; i++) {
        const p = x[i].codePointAt(0);
        const q = y[i].codePointAt(0);
        if (p !== q) return p < q ? -1 : 1;
      }
      return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
    }
    case BYTES: {
      const n = Math.min(a.length, b.length);
      for (let i = 0; i < n; i++) {
        if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
      }
      return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
    }
    case TUPLE: {
      const x = a.items;
      const y = b.items;
      const n = Math.min(x.length, y.length);
      for (let i = 0; i < n; i++) {
        if (keyId(x[i]) === keyId(y[i])) continue;
        return pyCompare(x[i], y[i]);
      }
      return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
    }
    case DATE:
    case DATETIME: {
      if (ca === DATETIME) {
        const na = a.tzOffsetMinutes === null;
        const nb = b.tzOffsetMinutes === null;
        if (na !== nb) {
          throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
        }
      }
      const x = dateTuple(a);
      const y = dateTuple(b);
      let ax = 0;
      let by = 0;
      if (a instanceof PyDateTime && a.tzOffsetMinutes !== null) ax = a.tzOffsetMinutes;
      if (b instanceof PyDateTime && b.tzOffsetMinutes !== null) by = b.tzOffsetMinutes;
      if (ax !== by) {
        // Compare in UTC by shifting minutes.
        const am = ((x[0] * 12 + x[1]) * 31 + x[2]) * 1440 + x[3] * 60 + x[4] - ax;
        const bm = ((y[0] * 12 + y[1]) * 31 + y[2]) * 1440 + y[3] * 60 + y[4] - by;
        if (am !== bm) return am < bm ? -1 : 1;
      }
      for (let i = 0; i < x.length; i++) {
        if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1;
      }
      return 0;
    }
    default:
      throw new PyTypeError('unorderable');
  }
}

/**
 * `sorted(pairs)` over (key, value) tuples.  Returns null when Python would
 * raise TypeError, in which case PyYAML keeps the original order.
 */
export function sortedPairs(pairs) {
  if (pairs.length < 2) return pairs.slice();
  try {
    const decorated = pairs.map((p, i) => ({ p, i }));
    decorated.sort((x, y) => {
      const c = pyCompare(x.p[0], y.p[0]);
      return c !== 0 ? c : x.i - y.i;
    });
    return decorated.map((d) => d.p);
  } catch (err) {
    if (err instanceof PyTypeError) return null;
    throw err;
  }
}

toolUseResult.content:
// A small model of the Python runtime values that PyYAML's safe loader can
// produce, plus the pieces of Python semantics the dumper depends on.
//
// Mapping of Python types onto JavaScript:
//   None      -> null
//   bool      -> boolean
//   int       -> BigInt          (arbitrary precision, like Python)
//   float     -> number          (IEEE-754 double, like Python)
//   str       -> string
//   bytes     -> Uint8Array
//   list      -> Array
//   tuple     -> PyTuple
//   dict      -> PyDict          (insertion ordered, Python key equality)
//   set       -> PySet
//   date      -> PyDate
//   datetime  -> PyDateTime

import { zfill } from './chars.mjs';

/** Raised where CPython would raise TypeError. */
export class PyTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TypeError';
  }
}

/** Raised where CPython would raise ValueError. */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export function isBytes(v) {
  return v instanceof Uint8Array;
}

// ---------------------------------------------------------------------------
// Key identity
// ---------------------------------------------------------------------------

let nanCounter = 0;

/**
 * Canonical key string reproducing Python's `==`/`hash` behaviour for the
 * hashable types safe_load can build.  In Python `True == 1 == 1.0`, so all
 * three have to collapse onto one slot.
 */
export function keyId(key) {
  if (key === null) return 'n';
  if (typeof key === 'boolean') return 'i' + (key ? '1' : '0');
  if (typeof key === 'bigint') return 'i' + key.toString();
  if (typeof key === 'number') {
    if (Number.isNaN(key)) return 'x' + (nanCounter++);
    if (key === Infinity) return 'f+inf';
    if (key === -Infinity) return 'f-inf';
    if (Number.isInteger(key)) return 'i' + BigInt(key).toString();
    return 'f' + key;
  }
  if (typeof key === 'string') return 's' + key;
  if (isBytes(key)) return 'b' + Array.from(key).join(',');
  if (key instanceof PyTuple) {
    return 't(' + key.items.map(keyId).join('') + ')';
  }
  if (key instanceof PyDate) return 'd' + key.isoformat();
  return 'o' + objectId(key);
}

const idMap = new WeakMap();
let idCounter = 0;

/** Stand-in for CPython's `id()`, used for alias detection. */
export function objectId(obj) {
  if (obj === null || (typeof obj !== 'object' && typeof obj !== 'function')) {
    return 'v' + String(obj);
  }
  let id = idMap.get(obj);
  if (id === undefined) {
    id = 'o' + (idCounter++);
    idMap.set(obj, id);
  }
  return id;
}

export class PyDict {
  constructor() {
    this.map = new Map(); // keyId -> [key, value]
  }

  get size() {
    return this.map.size;
  }

  set(key, value) {
    const id = keyId(key);
    const existing = this.map.get(id);
    // Python keeps the *first* key object but the last value.
    if (existing !== undefined) existing[1] = value;
    else this.map.set(id, [key, value]);
  }

  has(key) {
    return this.map.has(keyId(key));
  }

  get(key) {
    const e = this.map.get(keyId(key));
    return e === undefined ? undefined : e[1];
  }

  /** Entries in insertion order, as [key, value] pairs. */
  items() {
    return Array.from(this.map.values(), (e) => [e[0], e[1]]);
  }

  keys() {
    return Array.from(this.map.values(), (e) => e[0]);
  }

  /** dict.update(other) -- other's entries win, insertion order preserved. */
  update(other) {
    for (const [k, v] of other.items()) this.set(k, v);
  }
}

export class PySet {
  constructor() {
    this.map = new Map(); // keyId -> key
  }

  get size() {
    return this.map.size;
  }

  add(key) {
    const id = keyId(key);
    if (!this.map.has(id)) this.map.set(id, key);
  }

  values() {
    return Array.from(this.map.values());
  }
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeap(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

export function daysInMonth(year, month) {
  if (month === 2 && isLeap(year)) return 29;
  return DAYS_IN_MONTH[month - 1];
}

export class PyDate {
  constructor(year, month, day) {
    if (year < 1 || year > 9999) {
      throw new PyValueError(`year ${year} is out of range`);
    }
    if (month < 1 || month > 12) {
      throw new PyValueError('month must be in 1..12');
    }
    const limit = daysInMonth(year, month);
    if (day < 1 || day > limit) {
      throw new PyValueError(`day is out of range for month`);
    }
    this.year = year;
    this.month = month;
    this.day = day;
  }

  isoformat() {
    return `${zfill(this.year, 4)}-${zfill(this.month, 2)}-${zfill(this.day, 2)}`;
  }
}

export class PyDateTime extends PyDate {
  constructor(year, month, day, hour, minute, second, microsecond, tzOffsetMinutes) {
    super(year, month, day);
    if (hour < 0 || hour > 23) throw new PyValueError('hour must be in 0..23');
    if (minute < 0 || minute > 59) throw new PyValueError('minute must be in 0..59');
    if (second < 0 || second > 59) throw new PyValueError('second must be in 0..59');
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    // null means a naive datetime.
    this.tzOffsetMinutes = tzOffsetMinutes === undefined ? null : tzOffsetMinutes;
  }

  isoformat(sep = 'T') {
    let s = `${zfill(this.year, 4)}-${zfill(this.month, 2)}-${zfill(this.day, 2)}` +
      sep +
      `${zfill(this.hour, 2)}:${zfill(this.minute, 2)}:${zfill(this.second, 2)}`;
    if (this.microsecond) s += '.' + zfill(this.microsecond, 6);
    if (this.tzOffsetMinutes !== null) {
      const total = this.tzOffsetMinutes;
      const sign = total < 0 ? '-' : '+';
      const abs = Math.abs(total);
      s += `${sign}${zfill(Math.floor(abs / 60), 2)}:${zfill(abs % 60, 2)}`;
    }
    return s;
  }
}

// ---------------------------------------------------------------------------
// repr()
// ---------------------------------------------------------------------------

/**
 * CPython's `repr()` for floats: the shortest digit string that round-trips,
 * switching to exponential notation when decpt <= -4 or decpt > 16.
 */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  const negative = value < 0 || Object.is(value, -0);
  const abs = Math.abs(value);
  if (abs === 0) return negative ? '-0.0' : '0.0';

  // `toExponential()` with no argument yields the shortest round-tripping
  // digit string, which is exactly what CPython's repr is built from.
  const text = abs.toExponential();
  let digits = '';
  let exponent = 0;
  let i = 0;
  for (; i < text.length; i++) {
    const ch = text[i];
    if (ch === 'e') break;
    if (ch !== '.') digits += ch;
  }
  i++; // skip 'e'
  let expSign = 1;
  if (text[i] === '+') i++;
  else if (text[i] === '-') { expSign = -1; i++; }
  for (; i < text.length; i++) exponent = exponent * 10 + (text.charCodeAt(i) - 48);
  exponent *= expSign;

  // Strip trailing zeros of the digit string (CPython works with the shortest
  // significant-digit form).
  let end = digits.length;
  while (end > 1 && digits[end - 1] === '0') end--;
  digits = digits.slice(0, end);

  const decpt = exponent + 1; // value === 0.<digits> * 10**decpt
  let body;
  if (decpt <= -4 || decpt > 16) {
    body = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const e = decpt - 1;
    body += 'e' + (e < 0 ? '-' : '+') + zfill(Math.abs(e), 2);
  } else if (decpt <= 0) {
    body = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    body = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return negative ? '-' + body : body;
}

// ---------------------------------------------------------------------------
// Ordering
// ---------------------------------------------------------------------------

const NUMBER = 1;
const STRING = 2;
const BYTES = 3;
const TUPLE = 4;
const DATE = 5;
const DATETIME = 6;
const OTHER = 0;

function orderClass(v) {
  if (typeof v === 'boolean' || typeof v === 'bigint' || typeof v === 'number') return NUMBER;
  if (typeof v === 'string') return STRING;
  if (isBytes(v)) return BYTES;
  if (v instanceof PyTuple) return TUPLE;
  if (v instanceof PyDateTime) return DATETIME;
  if (v instanceof PyDate) return DATE;
  return OTHER;
}

function typeName(v) {
  if (v === null) return 'NoneType';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'number') return 'float';
  if (typeof v === 'string') return 'str';
  if (isBytes(v)) return 'bytes';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDateTime) return 'datetime.datetime';
  if (v instanceof PyDate) return 'datetime.date';
  if (v instanceof PyDict) return 'dict';
  if (v instanceof PySet) return 'set';
  if (Array.isArray(v)) return 'list';
  return 'object';
}

function numeric(v) {
  if (typeof v === 'boolean') return v ? 1 : 0;
  if (typeof v === 'bigint') return v;
  return v;
}

function compareNumbers(a, b) {
  const x = numeric(a);
  const y = numeric(b);
  if (typeof x === 'bigint' && typeof y === 'bigint') {
    return x < y ? -1 : x > y ? 1 : 0;
  }
  // Mixed int/float: compare exactly where it matters by promoting the float.
  let xv = x;
  let yv = y;
  if (typeof xv === 'bigint') {
    if (Number.isNaN(yv)) return NaN;
    if (yv === Infinity) return -1;
    if (yv === -Infinity) return 1;
    if (Number.isInteger(yv)) { yv = BigInt(yv); return xv < yv ? -1 : xv > yv ? 1 : 0; }
    const xf = Number(xv);
    return xf < yv ? -1 : xf > yv ? 1 : 0;
  }
  if (typeof yv === 'bigint') {
    if (Number.isNaN(xv)) return NaN;
    if (xv === Infinity) return 1;
    if (xv === -Infinity) return -1;
    if (Number.isInteger(xv)) { xv = BigInt(xv); return xv < yv ? -1 : xv > yv ? 1 : 0; }
    const yf = Number(yv);
    return xv < yf ? -1 : xv > yf ? 1 : 0;
  }
  if (Number.isNaN(xv) || Number.isNaN(yv)) return NaN;
  return xv < yv ? -1 : xv > yv ? 1 : 0;
}

function dateTuple(v) {
  const base = [v.year, v.month, v.day];
  if (v instanceof PyDateTime) {
    base.push(v.hour, v.minute, v.second, v.microsecond);
  }
  return base;
}

/**
 * Three-way comparison following CPython's rules; throws PyTypeError for
 * unorderable pairs, exactly where Python's `<` would.
 */
export function pyCompare(a, b) {
  const ca = orderClass(a);
  const cb = orderClass(b);
  if (ca === OTHER || cb === OTHER || ca !== cb) {
    throw new PyTypeError(
      `'<' not supported between instances of '${typeName(a)}' and '${typeName(b)}'`);
  }
  switch (ca) {
    case NUMBER: {
      const r = compareNumbers(a, b);
      return Number.isNaN(r) ? 0 : r;
    }
    case STRING: {
      // Python compares str by code point.
      const x = Array.from(a);
      const y = Array.from(b);
      const n = Math.min(x.length, y.length);
      for (let i = 0; i < n; i++) {
        const p = x[i].codePointAt(0);
        const q = y[i].codePointAt(0);
        if (p !== q) return p < q ? -1 : 1;
      }
      return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
    }
    case BYTES: {
      const n = Math.min(a.length, b.length);
      for (let i = 0; i < n; i++) {
        if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
      }
      return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
    }
    case TUPLE: {
      const x = a.items;
      const y = b.items;
      const n = Math.min(x.length, y.length);
      for (let i = 0; i < n; i++) {
        if (keyId(x[i]) === keyId(y[i])) continue;
        return pyCompare(x[i], y[i]);
      }
      return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
    }
    case DATE:
    case DATETIME: {
      if (ca === DATETIME) {
        const na = a.tzOffsetMinutes === null;
        const nb = b.tzOffsetMinutes === null;
        if (na !== nb) {
          throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
        }
      }
      const x = dateTuple(a);
      const y = dateTuple(b);
      let ax = 0;
      let by = 0;
      if (a instanceof PyDateTime && a.tzOffsetMinutes !== null) ax = a.tzOffsetMinutes;
      if (b instanceof PyDateTime && b.tzOffsetMinutes !== null) by = b.tzOffsetMinutes;
      if (ax !== by) {
        // Compare in UTC by shifting minutes.
        const am = ((x[0] * 12 + x[1]) * 31 + x[2]) * 1440 + x[3] * 60 + x[4] - ax;
        const bm = ((y[0] * 12 + y[1]) * 31 + y[2]) * 1440 + y[3] * 60 + y[4] - by;
        if (am !== bm) return am < bm ? -1 : 1;
      }
      for (let i = 0; i < x.length; i++) {
        if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1;
      }
      return 0;
    }
    default:
      throw new PyTypeError('unorderable');
  }
}

/**
 * `sorted(pairs)` over (key, value) tuples.  Returns null when Python would
 * raise TypeError, in which case PyYAML keeps the original order.
 */
export function sortedPairs(pairs) {
  if (pairs.length < 2) return pairs.slice();
  try {
    const decorated = pairs.map((p, i) => ({ p, i }));
    decorated.sort((x, y) => {
      const c = pyCompare(x.p[0], y.p[0]);
      return c !== 0 ? c : x.i - y.i;
    });
    return decorated.map((d) => d.p);
  } catch (err) {
    if (err instanceof PyTypeError) return null;
    throw err;
  }
}

