// Token types produced by the scanner (PyYAML's tokens module).

export class Token {
  constructor(id, startMark, endMark) {
    this.id = id;
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

export function makeToken(id, startMark, endMark) {
  return new Token(id, startMark, endMark);
}

export class DirectiveToken extends Token {
  constructor(name, value, startMark, endMark) {
    super('<directive>', startMark, endMark);
    this.name = name;
    this.value = value;
  }
}

export class AliasToken extends Token {
  constructor(value, startMark, endMark) {
    super('<alias>', startMark, endMark);
    this.value = value;
  }
}

export class AnchorToken extends Token {
  constructor(value, startMark, endMark) {
    super('<anchor>', startMark, endMark);
    this.value = value;
  }
}

export class TagToken extends Token {
  constructor(value, startMark, endMark) {
    super('<tag>', startMark, endMark);
    this.value = value; // [handle, suffix]
  }
}

export class ScalarToken extends Token {
  constructor(value, plain, startMark, endMark, style = null) {
    super('<scalar>', startMark, endMark);
    this.value = value;
    this.plain = plain;
    this.style = style;
  }
}

// Simple marker token ids, used with makeToken().
export const T = {
  STREAM_START: '<stream start>',
  STREAM_END: '<stream end>',
  DOCUMENT_START: '<document start>',
  DOCUMENT_END: '<document end>',
  BLOCK_SEQUENCE_START: '<block sequence start>',
  BLOCK_MAPPING_START: '<block mapping start>',
  BLOCK_END: '<block end>',
  FLOW_SEQUENCE_START: '[',
  FLOW_MAPPING_START: '{',
  FLOW_SEQUENCE_END: ']',
  FLOW_MAPPING_END: '}',
  KEY: '?',
  VALUE: ':',
  BLOCK_ENTRY: '-',
  FLOW_ENTRY: ',',
  DIRECTIVE: '<directive>',
  ALIAS: '<alias>',
  ANCHOR: '<anchor>',
  TAG: '<tag>',
  SCALAR: '<scalar>',
};

