// Reader: turns the input string into a code-point buffer with position
// tracking, mirroring PyYAML's reader module for str inputs.

import { Mark, ReaderError } from './errors.mjs';
import { toCodePoints } from './chars.mjs';

function isPrintable(cp) {
  return cp === 0x09 || cp === 0x0a || cp === 0x0d ||
    (cp >= 0x20 && cp <= 0x7e) ||
    cp === 0x85 ||
    (cp >= 0xa0 && cp <= 0xd7ff) ||
    (cp >= 0xe000 && cp <= 0xfffd) ||
    (cp >= 0x10000 && cp <= 0x10ffff);
}

export class Reader {
  constructor(stream) {
    this.name = '<unicode string>';
    this.chars = toCodePoints(stream);
    this.checkPrintable();
    this.chars.push('\0');
    this.buffer = stream;
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  checkPrintable() {
    for (let i = 0; i < this.chars.length; i++) {
      const cp = this.chars[i].codePointAt(0);
      if (!isPrintable(cp)) {
