// Reader: turns the input string into a code-point buffer with position
// tracking, mirroring PyYAML's reader module for str inputs.

import { Mark, ReaderError } from './errors.mjs';
import { toCodePoints } from './chars.mjs';

function isPrintable(cp) {
  return cp === 0x09 || cp === 0x0a || cp === 0x0d ||
    (cp >= 0x20 && cp <= 0x7e) ||
    cp === 0x85 ||
    (cp >= 0xa0 && cp <= 0xd7ff) ||
    (cp >= 0xe000 && cp <= 0xfffd) ||
    (cp >= 0x10000 && cp <= 0x10ffff);
}

export class Reader {
  constructor(stream) {
    this.name = '<unicode string>';
    this.chars = toCodePoints(stream);
    this.checkPrintable();
    this.chars.push('\0');
    this.buffer = stream;
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  checkPrintable() {
    for (let i = 0; i < this.chars.length; i++) {
      const cp = this.chars[i].codePointAt(0);
      if (!isPrintable(cp)) {
        throw new ReaderError(this.name, i, cp, 'unicode',
          'special characters are not allowed');
      }
    }
  }

  peek(index = 0) {
    const ch = this.chars[this.pointer + index];
    return ch === undefined ? '\0' : ch;
  }

  prefix(length = 1) {
    let out = '';
    for (let i = 0; i < length; i++) {
      const ch = this.chars[this.pointer + i];
      if (ch === undefined) break;
      out += ch;
    }
    return out;
  }

  forward(length = 1) {
    while (length) {
      const ch = this.chars[this.pointer];
      if (ch === undefined) break;
      this.pointer += 1;
      this.index += 1;
      if (ch === '\n' || ch === '\x85' || ch === ' ' || ch === ' ' ||
        (ch === '\r' && this.chars[this.pointer] !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== '﻿') {
        this.column += 1;
      }
      length -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column,
      this.buffer, this.index);
  }
}

