// Scanner: characters -> tokens.  A faithful port of PyYAML's scanner.

import { ScannerError } from './errors.mjs';
import { inChars, isLineBreak, isDigit, isHexDigit, isAlpha, hexValue } from './chars.mjs';
import {
  makeToken, T, DirectiveToken, AliasToken, AnchorToken, TagToken, ScalarToken,
} from './tokens.mjs';

const WSZ = '\0 \t\r\n\x85  ';   // '\0', space, tab, all line breaks
const BREAKZ = '\0\r\n\x85  ';   // '\0' and all line breaks
const SPACES_BREAKZ = ' \r\n\x85  ';

const ESCAPE_REPLACEMENTS = new Map([
  ['0', '\0'], ['a', '\x07'], ['b', '\b'], ['t', '\t'], ['\t', '\t'],
  ['n', '\n'], ['v', '\v'], ['f', '\f'], ['r', '\r'], ['e', '\x1b'],
  [' ', ' '], ['"', '"'], ['\\', '\\'], ['/', '/'], ['N', '\x85'],
  ['_', '\xa0'], ['L', ' '], ['P', ' '],
]);

const ESCAPE_CODES = new Map([['x', 2], ['u', 4], ['U', 8]]);

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner {
  constructor(reader) {
    this.reader = reader;
    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();
    this.fetchStreamStart();
  }

  // -- reader shortcuts ------------------------------------------------
  peek(i = 0) { return this.reader.peek(i); }
  prefix(n = 1) { return this.reader.prefix(n); }
  forward(n = 1) { this.reader.forward(n); }
  getMark() { return this.reader.getMark(); }
  get column() { return this.reader.column; }
  get line() { return this.reader.line; }
  get index() { return this.reader.index; }

  // -- public API ------------------------------------------------------
  checkToken(...ids) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      if (ids.length === 0) return true;
      for (const id of ids) if (this.tokens[0].id === id) return true;
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    return this.tokens.length ? this.tokens[0] : null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      this.tokensTaken += 1;
      return this.tokens.shift();
    }
    return null;
  }

  // -- token fetching --------------------------------------------------
  needMoreTokens() {
    if (this.done) return false;
    if (this.tokens.length === 0) return true;
    this.staleP0ssibleSimpleKeys();
    if (this.nextPossibleSimpleKey() === this.tokensTaken) return true;
    return false;
  }

  fetchMoreTokens() {
    this.scanToNextToken();
    this.staleP0ssibleSimpleKeys();
    this.unwindIndent(this.column);

    const ch = this.peek();
    if (ch === '\0') return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowSequenceStart();
    if (ch === '{') return this.fetchFlowMappingStart();
    if (ch === ']') return this.fetchFlowSequenceEnd();
    if (ch === '}') return this.fetchFlowMappingEnd();
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && !this.flowLevel) return this.fetchLiteral();
    if (ch === '>' && !this.flowLevel) return this.fetchFolded();
    if (ch === "'") return this.fetchSingle();
    if (ch === '"') return this.fetchDouble();
    if (this.checkPlain()) return this.fetchPlain();

    throw new ScannerError('while scanning for the next token', null,
      `found character ${JSONless(ch)} that cannot start any token`,
      this.getMark());
  }

  // -- simple keys -----------------------------------------------------
  nextPossibleSimpleKey() {
    let minTokenNumber = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (minTokenNumber === null || key.tokenNumber < minTokenNumber) {
        minTokenNumber = key.tokenNumber;
      }
    }
    return minTokenNumber;
  }

  staleP0ssibleSimpleKeys() {
    for (const level of Array.from(this.possibleSimpleKeys.keys())) {
      const key = this.possibleSimpleKeys.get(level);
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError('while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark());
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    const required = !this.flowLevel && this.indent === this.column;
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const tokenNumber = this.tokensTaken + this.tokens.length;
      this.possibleSimpleKeys.set(this.flowLevel,
        new SimpleKey(tokenNumber, required, this.index, this.line,
          this.column, this.getMark()));
    }
  }

  removePossibleSimpleKey() {
    const key = this.possibleSimpleKeys.get(this.flowLevel);
    if (key !== undefined) {
      if (key.required) {
        throw new ScannerError('while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark());
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  // -- indentation -----------------------------------------------------
  unwindIndent(column) {
    if (this.flowLevel) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(makeToken(T.BLOCK_END, mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  // -- fetchers --------------------------------------------------------
  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(makeToken(T.STREAM_START, mark, mark));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.getMark();
    this.tokens.push(makeToken(T.STREAM_END, mark, mark));
    this.done = true;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
  }

  fetchDocumentStart() { this.fetchDocumentIndicator(T.DOCUMENT_START); }
  fetchDocumentEnd() { this.fetchDocumentIndicator(T.DOCUMENT_END); }

  fetchDocumentIndicator(id) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    this.tokens.push(makeToken(id, startMark, this.getMark()));
  }

  fetchFlowSequenceStart() { this.fetchFlowCollectionStart(T.FLOW_SEQUENCE_START); }
  fetchFlowMappingStart() { this.fetchFlowCollectionStart(T.FLOW_MAPPING_START); }

  fetchFlowCollectionStart(id) {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(makeToken(id, startMark, this.getMark()));
  }

  fetchFlowSequenceEnd() { this.fetchFlowCollectionEnd(T.FLOW_SEQUENCE_END); }
  fetchFlowMappingEnd() { this.fetchFlowCollectionEnd(T.FLOW_MAPPING_END); }

  fetchFlowCollectionEnd(id) {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(makeToken(id, startMark, this.getMark()));
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(makeToken(T.FLOW_ENTRY, startMark, this.getMark()));
  }

  fetchBlockEntry() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null, 'sequence entries are not allowed here',
          this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(makeToken(T.BLOCK_SEQUENCE_START, mark, mark));
      }
    }
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(makeToken(T.BLOCK_ENTRY, startMark, this.getMark()));
  }

  fetchKey() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null, 'mapping keys are not allowed here',
          this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(makeToken(T.BLOCK_MAPPING_START, mark, mark));
      }
    }
    this.allowSimpleKey = !this.flowLevel;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(makeToken(T.KEY, startMark, this.getMark()));
  }

  fetchValue() {
    const key = this.possibleSimpleKeys.get(this.flowLevel);
    if (key !== undefined) {
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
        makeToken(T.KEY, key.mark, key.mark));
      if (!this.flowLevel) {
        if (this.addIndent(key.column)) {
          this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
            makeToken(T.BLOCK_MAPPING_START, key.mark, key.mark));
        }
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(null, null,
            'mapping values are not allowed here', this.getMark());
        }
      }
      if (!this.flowLevel) {
        if (this.addIndent(this.column)) {
          const mark = this.getMark();
          this.tokens.push(makeToken(T.BLOCK_MAPPING_START, mark, mark));
        }
      }
      this.allowSimpleKey = !this.flowLevel;
      this.removePossibleSimpleKey();
    }
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(makeToken(T.VALUE, startMark, this.getMark()));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AliasToken));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AnchorToken));
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  fetchLiteral() { this.fetchBlockScalar('|'); }
  fetchFolded() { this.fetchBlockScalar('>'); }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchSingle() { this.fetchFlowScalar("'"); }
  fetchDouble() { this.fetchFlowScalar('"'); }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  // -- checkers --------------------------------------------------------
  checkDirective() {
    return this.column === 0;
  }

  checkDocumentStart() {
    if (this.column === 0) {
      if (this.prefix(3) === '---' && inChars(this.peek(3), WSZ)) return true;
    }
    return false;
  }

  checkDocumentEnd() {
    if (this.column === 0) {
      if (this.prefix(3) === '...' && inChars(this.peek(3), WSZ)) return true;
    }
    return false;
  }

  checkBlockEntry() {
    return inChars(this.peek(1), WSZ);
  }

  checkKey() {
    if (this.flowLevel) return true;
    return inChars(this.peek(1), WSZ);
  }

  checkValue() {
    if (this.flowLevel) return true;
    return inChars(this.peek(1), WSZ);
  }

  checkPlain() {
    const ch = this.peek();
    if (!inChars(ch, '\0 \t\r\n\x85  -?:,[]{}#&*!|>\'"%@`')) return true;
    return !inChars(this.peek(1), WSZ) &&
      (ch === '-' || (!this.flowLevel && (ch === '?' || ch === ':')));
  }

  // -- scanners --------------------------------------------------------
  scanToNextToken() {
    if (this.index === 0 && this.peek() === '﻿') this.forward();
    let found = false;
    while (!found) {
      while (this.peek() === ' ') this.forward();
      if (this.peek() === '#') {
        while (!inChars(this.peek(), BREAKZ)) this.forward();
      }
      if (this.scanLineBreak()) {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!inChars(this.peek(), BREAKZ)) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return new DirectiveToken(name, value, startMark, endMark);
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isAlpha(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${repr(ch)}`,
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!inChars(ch, '\0 \r\n\x85  ')) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${repr(ch)}`,
        this.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or '.', but found ${repr(this.peek())}`, this.getMark());
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!inChars(this.peek(), '\0 \r\n\x85  ')) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or ' ', but found ${repr(this.peek())}`, this.getMark());
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!isDigit(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit, but found ${repr(ch)}`, this.getMark());
    }
    let length = 0;
    while (isDigit(this.peek(length))) length += 1;
    const value = Number(this.prefix(length));
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === ' ') this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    if (this.peek() !== ' ') {
      throw new ScannerError('while scanning a directive', startMark,
        `expected ' ', but found ${repr(this.peek())}`, this.getMark());
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    if (!inChars(this.peek(), '\0 \r\n\x85  ')) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected ' ', but found ${repr(this.peek())}`, this.getMark());
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!inChars(this.peek(), BREAKZ)) this.forward();
    }
    if (!inChars(this.peek(), BREAKZ)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a comment or a line break, but found ${repr(this.peek())}`,
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanAnchor(TokenClass) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isAlpha(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError(`while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${repr(ch)}`,
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!inChars(ch, '\0 \t\r\n\x85  ?:,]}%@`')) {
      throw new ScannerError(`while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${repr(ch)}`,
        this.getMark());
    }
    return new TokenClass(value, startMark, this.getMark());
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle = null;
    let suffix = null;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError('while parsing a tag', startMark,
          `expected '>', but found ${repr(this.peek())}`, this.getMark());
      }
      this.forward();
    } else if (inChars(ch, WSZ)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!inChars(ch, '\0 \r\n\x85  ')) {
        if (ch === '!') { useHandle = true; break; }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!inChars(ch, '\0 \r\n\x85  ')) {
      throw new ScannerError('while scanning a tag', startMark,
        `expected ' ', but found ${repr(ch)}`, this.getMark());
    }
    return new TagToken([handle, suffix], startMark, this.getMark());
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();

    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);

    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let indent;
    let breaks;
    let endMark;
    if (increment === null) {
      const res = this.scanBlockScalarIndentation();
      breaks = res[0];
      const maxIndent = res[1];
      endMark = res[2];
      indent = Math.max(minIndent, maxIndent);
    } else {
      indent = minIndent + increment - 1;
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
    }

    let lineBreak = '';
    while (this.column === indent && this.peek() !== '\0') {
      chunks.push(...breaks);
      const leadingNonSpace = this.peek() !== ' ' && this.peek() !== '\t';
      let length = 0;
      while (!inChars(this.peek(length), BREAKZ)) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
      if (this.column === indent && this.peek() !== '\0') {
        if (folded && lineBreak === '\n' && leadingNonSpace &&
          this.peek() !== ' ' && this.peek() !== '\t') {
          if (breaks.length === 0) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }

    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) chunks.push(...breaks);

    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (isDigit(ch)) {
        increment = Number(ch);
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0',
            this.getMark());
        }
        this.forward();
      }
    } else if (isDigit(ch)) {
      increment = Number(ch);
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0',
          this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!inChars(ch, '\0 \r\n\x85  ')) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected chomping or indentation indicators, but found ${repr(ch)}`,
        this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!inChars(this.peek(), BREAKZ)) this.forward();
    }
    if (!inChars(this.peek(), BREAKZ)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected a comment or a line break, but found ${repr(this.peek())}`,
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (inChars(this.peek(), ' \r\n\x85  ')) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') this.forward();
    while (inChars(this.peek(), '\r\n\x85  ')) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    while (this.peek() !== quote) {
      chunks.push(...this.scanFlowScalarSpaces(double, startMark));
      chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    }
    this.forward();
    return new ScalarToken(chunks.join(''), false, startMark, this.getMark(), style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      while (!inChars(this.peek(length), '\'"\\\0 \t\r\n\x85  ')) length += 1;
      if (length) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === "'" && this.peek(1) === "'") {
        chunks.push("'");
        this.forward(2);
      } else if ((double && ch === "'") || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (ESCAPE_REPLACEMENTS.has(ch)) {
          chunks.push(ESCAPE_REPLACEMENTS.get(ch));
          this.forward();
        } else if (ESCAPE_CODES.has(ch)) {
          const length2 = ESCAPE_CODES.get(ch);
          this.forward();
          for (let k = 0; k < length2; k++) {
            if (!isHexDigit(this.peek(k))) {
              throw new ScannerError('while scanning a double-quoted scalar',
                startMark,
                `expected escape sequence of ${length2} hexadecimal numbers, but found ${repr(this.peek(k))}`,
                this.getMark());
            }
          }
          let code = 0;
          for (let k = 0; k < length2; k++) code = code * 16 + hexValue(this.peek(k));
          chunks.push(safeFromCodePoint(code, startMark, this.getMark()));
          this.forward(length2);
        } else if (inChars(ch, '\r\n\x85  ')) {
          this.scanLineBreak();
          chunks.push(...this.scanFlowScalarBreaks(double, startMark));
        } else {
          throw new ScannerError('while scanning a double-quoted scalar',
            startMark, `found unknown escape character ${repr(ch)}`, this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ' || this.peek(length) === '\t') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === '\0') {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    }
    if (inChars(ch, '\r\n\x85  ')) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      chunks.push(...breaks);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && inChars(this.peek(3), WSZ)) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark());
      }
      while (this.peek() === ' ' || this.peek() === '\t') this.forward();
      if (inChars(this.peek(), '\r\n\x85  ')) {
        chunks.push(this.scanLineBreak());
      } else {
        return chunks;
      }
    }
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      let length = 0;
      if (this.peek() === '#') break;
      for (;;) {
        const ch = this.peek(length);
        if (inChars(ch, WSZ) ||
          (ch === ':' && inChars(this.peek(length + 1),
            WSZ + (this.flowLevel ? ',[]{}' : ''))) ||
          (this.flowLevel && inChars(ch, ',?[]{}'))) {
          break;
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      chunks.push(...spaces);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (spaces.length === 0 || this.peek() === '#' ||
        (!this.flowLevel && this.column < indent)) {
        break;
      }
    }
    return new ScalarToken(chunks.join(''), true, startMark, endMark);
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (inChars(ch, '\r\n\x85  ')) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && inChars(this.peek(3), WSZ)) {
        return [];
      }
      const breaks = [];
      while (inChars(this.peek(), ' \r\n\x85  ')) {
        if (this.peek() === ' ') {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          const p = this.prefix(3);
          if ((p === '---' || p === '...') && inChars(this.peek(3), WSZ)) {
            return [];
          }
        }
      }
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      chunks.push(...breaks);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        `expected '!', but found ${repr(ch)}`, this.getMark());
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== ' ') {
      while (isAlpha(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError(`while scanning a ${name}`, startMark,
          `expected '!', but found ${repr(ch)}`, this.getMark());
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (isAlpha(ch) || inChars(ch, "-;/?:@&=+$,_.!~*'()[]%")) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (chunks.length === 0) {
      throw new ScannerError(`while parsing a ${name}`, startMark,
        `expected URI, but found ${repr(ch)}`, this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const bytes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k++) {
        if (!isHexDigit(this.peek(k))) {
          throw new ScannerError(`while scanning a ${name}`, startMark,
            `expected URI escape sequence of 2 hexadecimal numbers, but found ${repr(this.peek(k))}`,
            this.getMark());
        }
      }
      bytes.push(hexValue(this.peek(0)) * 16 + hexValue(this.peek(1)));
      this.forward(2);
    }
    try {
      return new TextDecoder('utf-8', { fatal: true }).decode(new Uint8Array(bytes));
    } catch (err) {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        String(err.message), mark);
    }
  }

  scanLineBreak() {
    const ch = this.peek();
    if (ch === '\r' || ch === '\n' || ch === '\x85') {
      if (this.prefix(2) === '\r\n') this.forward(2);
      else this.forward();
      return '\n';
    }
    if (ch === ' ' || ch === ' ') {
      this.forward();
      return ch;
    }
    return '';
  }
}

function safeFromCodePoint(code, startMark, mark) {
  if (code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) {
    throw new ScannerError('while scanning a double-quoted scalar', startMark,
      'found undefined escape character', mark);
  }
  return String.fromCodePoint(code);
}

/** Python-style repr() of a single character, used only in error messages. */
export function repr(ch) {
  if (ch === '\0') return "'\\x00'";
  if (ch === '\n') return "'\\n'";
  if (ch === '\r') return "'\\r'";
  if (ch === '\t') return "'\\t'";
  if (ch === "'") return '"\'"';
  return `'${ch}'`;
}

function JSONless(ch) {
  return repr(ch);
}

