// Events exchanged between parser/composer and serializer/emitter.

export class Event {
  constructor(startMark = null, endMark = null) {
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

export class NodeEvent extends Event {
  constructor(anchor, startMark, endMark) {
    super(startMark, endMark);
    this.anchor = anchor;
  }
}

export class CollectionStartEvent extends NodeEvent {
  constructor(anchor, tag, implicit, startMark, endMark, flowStyle = null) {
    super(anchor, startMark, endMark);
    this.tag = tag;
    this.implicit = implicit;
    this.flowStyle = flowStyle;
  }
}

export class CollectionEndEvent extends Event {}

export class StreamStartEvent extends Event {
  constructor(startMark, endMark, encoding = null) {
    super(startMark, endMark);
    this.encoding = encoding;
  }
}

export class StreamEndEvent extends Event {}

export class DocumentStartEvent extends Event {
  constructor(startMark, endMark, explicit = null, version = null, tags = null) {
    super(startMark, endMark);
