// Parser: tokens -> events.  A faithful port of PyYAML's parser.

import { ParserError } from './errors.mjs';
import { T } from './tokens.mjs';
import {
  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
  MappingStartEvent, MappingEndEvent,
} from './events.mjs';

const DEFAULT_TAGS = new Map([['!', '!'], ['!!', 'tag:yaml.org,2002:']]);

export class Parser {
  constructor(scanner) {
    this.scanner = scanner;
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = new Map();
    this.states = [];
    this.marks = [];
    this.state = this.parseStreamStart;
  }

  checkEvent(...classes) {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state.call(this);
    }
    if (this.currentEvent !== null) {
      if (classes.length === 0) return true;
      for (const cls of classes) {
        if (this.currentEvent instanceof cls) return true;
      }
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state.call(this);
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state.call(this);
    }
    const event = this.currentEvent;
    this.currentEvent = null;
    return event;
  }

  // -- stream ----------------------------------------------------------
  parseStreamStart() {
    const token = this.scanner.getToken();
    const event = new StreamStartEvent(token.startMark, token.endMark, null);
    this.state = this.parseImplicitDocumentStart;
    return event;
  }

  parseImplicitDocumentStart() {
    if (!this.scanner.checkToken(T.DIRECTIVE, T.DOCUMENT_START, T.STREAM_END)) {
      this.tagHandles = new Map(DEFAULT_TAGS);
      const token = this.scanner.peekToken();
      const event = new DocumentStartEvent(token.startMark, token.startMark, false);
      this.states.push(this.parseDocumentEnd);
      this.state = this.parseBlockNode;
      return event;
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.scanner.checkToken(T.DOCUMENT_END)) this.scanner.getToken();
    if (!this.scanner.checkToken(T.STREAM_END)) {
      let token = this.scanner.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.scanner.checkToken(T.DOCUMENT_START)) {
        throw new ParserError(null, null,
          `expected '<document start>', but found ${this.scanner.peekToken().id}`,
          this.scanner.peekToken().startMark);
      }
      token = this.scanner.getToken();
      const endMark = token.endMark;
      const event = new DocumentStartEvent(startMark, endMark, true, version, tags);
      this.states.push(this.parseDocumentEnd);
      this.state = this.parseDocumentContent;
      return event;
    }
    const token = this.scanner.getToken();
    const event = new StreamEndEvent(token.startMark, token.endMark);
    if (this.states.length) throw new Error('assertion failed: states');
    if (this.marks.length) throw new Error('assertion failed: marks');
    this.state = null;
    return event;
  }

  parseDocumentEnd() {
    let token = this.scanner.peekToken();
    const startMark = token.startMark;
    let endMark = startMark;
    let explicit = false;
    if (this.scanner.checkToken(T.DOCUMENT_END)) {
      token = this.scanner.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    const event = new DocumentEndEvent(startMark, endMark, explicit);
    this.state = this.parseDocumentStart;
    return event;
  }

  parseDocumentContent() {
    if (this.scanner.checkToken(T.DIRECTIVE, T.DOCUMENT_START, T.DOCUMENT_END,
      T.STREAM_END)) {
      const event = this.processEmptyScalar(this.scanner.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = new Map();
    while (this.scanner.checkToken(T.DIRECTIVE)) {
      const token = this.scanner.getToken();
      if (token.name === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive',
            token.startMark);
        }
        const [major] = token.value;
        if (major !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark);
        }
        this.yamlVersion = token.value;
      } else if (token.name === 'TAG') {
        const [handle, prefix] = token.value;
        if (this.tagHandles.has(handle)) {
          throw new ParserError(null, null,
            `duplicate tag handle ${handle}`, token.startMark);
        }
        this.tagHandles.set(handle, prefix);
      }
    }
    let value = null;
    if (this.tagHandles.size) value = new Map(this.tagHandles);
    for (const [key, prefix] of DEFAULT_TAGS) {
      if (!this.tagHandles.has(key)) this.tagHandles.set(key, prefix);
    }
    return [this.yamlVersion, value];
  }

  // -- nodes -----------------------------------------------------------
  parseBlockNode() {
    return this.parseNode(true, false);
  }

  parseFlowNode() {
    return this.parseNode(false, false);
  }

  parseBlockNodeOrIndentlessSequence() {
    return this.parseNode(true, true);
  }

  parseNode(block = false, indentlessSequence = false) {
    if (this.scanner.checkToken(T.ALIAS)) {
      const token = this.scanner.getToken();
      const event = new AliasEvent(token.value, token.startMark, token.endMark);
      this.state = this.states.pop();
      return event;
    }
    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    if (this.scanner.checkToken(T.ANCHOR)) {
      let token = this.scanner.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.scanner.checkToken(T.TAG)) {
        token = this.scanner.getToken();
        tagMark = token.startMark;
        endMark = token.endMark;
        tag = token.value;
      }
    } else if (this.scanner.checkToken(T.TAG)) {
      let token = this.scanner.getToken();
      startMark = token.startMark;
      tagMark = token.startMark;
      endMark = token.endMark;
      tag = token.value;
      if (this.scanner.checkToken(T.ANCHOR)) {
        token = this.scanner.getToken();
        endMark = token.endMark;
        anchor = token.value;
      }
    }
    if (tag !== null) {
      const [handle, suffix] = tag;
      if (handle !== null) {
        if (!this.tagHandles.has(handle)) {
          throw new ParserError('while parsing a node', startMark,
            `found undefined tag handle ${handle}`, tagMark);
        }
        tag = this.tagHandles.get(handle) + suffix;
      } else {
        tag = suffix;
      }
    }
    if (startMark === null) {
      startMark = this.scanner.peekToken().startMark;
      endMark = startMark;
    }
    let event = null;
    const implicit = tag === null || tag === '!';
    if (indentlessSequence && this.scanner.checkToken(T.BLOCK_ENTRY)) {
      endMark = this.scanner.peekToken().endMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark);
      this.state = this.parseIndentlessSequenceEntry;
      return event;
    }
    if (this.scanner.checkToken(T.SCALAR)) {
      const token = this.scanner.getToken();
      endMark = token.endMark;
      let impl;
      if ((token.plain && tag === null) || tag === '!') impl = [true, false];
      else if (tag === null) impl = [false, true];
      else impl = [false, false];
      event = new ScalarEvent(anchor, tag, impl, token.value, startMark,
        endMark, token.style);
      this.state = this.states.pop();
      return event;
    }
    if (this.scanner.checkToken(T.FLOW_SEQUENCE_START)) {
      endMark = this.scanner.peekToken().endMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, true);
      this.state = this.parseFlowSequenceFirstEntry;
      return event;
    }
    if (this.scanner.checkToken(T.FLOW_MAPPING_START)) {
      endMark = this.scanner.peekToken().endMark;
      event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, true);
      this.state = this.parseFlowMappingFirstKey;
      return event;
    }
    if (block && this.scanner.checkToken(T.BLOCK_SEQUENCE_START)) {
      endMark = this.scanner.peekToken().startMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, false);
      this.state = this.parseBlockSequenceFirstEntry;
      return event;
    }
    if (block && this.scanner.checkToken(T.BLOCK_MAPPING_START)) {
      endMark = this.scanner.peekToken().startMark;
      event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, false);
      this.state = this.parseBlockMappingFirstKey;
      return event;
    }
    if (anchor !== null || tag !== null) {
      event = new ScalarEvent(anchor, tag, [implicit, false], '', startMark, endMark);
      this.state = this.states.pop();
      return event;
    }
    const node = block ? 'block' : 'flow';
    const token = this.scanner.peekToken();
    throw new ParserError(`while parsing a ${node} node`, startMark,
      `expected the node content, but found ${token.id}`, token.startMark);
  }

  // -- block sequence --------------------------------------------------
  parseBlockSequenceFirstEntry() {
    const token = this.scanner.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockSequenceEntry();
  }

  parseBlockSequenceEntry() {
    if (this.scanner.checkToken(T.BLOCK_ENTRY)) {
      const token = this.scanner.getToken();
      if (!this.scanner.checkToken(T.BLOCK_ENTRY, T.BLOCK_END)) {
        this.states.push(this.parseBlockSequenceEntry);
        return this.parseBlockNode();
      }
      this.state = this.parseBlockSequenceEntry;
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.scanner.checkToken(T.BLOCK_END)) {
      const token = this.scanner.peekToken();
      throw new ParserError('while parsing a block collection',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found ${token.id}`, token.startMark);
    }
    const token = this.scanner.getToken();
    const event = new SequenceEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseIndentlessSequenceEntry() {
    if (this.scanner.checkToken(T.BLOCK_ENTRY)) {
      const token = this.scanner.getToken();
      if (!this.scanner.checkToken(T.BLOCK_ENTRY, T.KEY, T.VALUE, T.BLOCK_END)) {
        this.states.push(this.parseIndentlessSequenceEntry);
        return this.parseBlockNode();
      }
      this.state = this.parseIndentlessSequenceEntry;
      return this.processEmptyScalar(token.endMark);
    }
    const token = this.scanner.peekToken();
    const event = new SequenceEndEvent(token.startMark, token.startMark);
    this.state = this.states.pop();
    return event;
  }

  // -- block mapping ---------------------------------------------------
  parseBlockMappingFirstKey() {
    const token = this.scanner.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockMappingKey();
  }

  parseBlockMappingKey() {
    if (this.scanner.checkToken(T.KEY)) {
      const token = this.scanner.getToken();
      if (!this.scanner.checkToken(T.KEY, T.VALUE, T.BLOCK_END)) {
        this.states.push(this.parseBlockMappingValue);
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = this.parseBlockMappingValue;
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.scanner.checkToken(T.BLOCK_END)) {
      const token = this.scanner.peekToken();
      throw new ParserError('while parsing a block mapping',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found ${token.id}`, token.startMark);
    }
    const token = this.scanner.getToken();
    const event = new MappingEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseBlockMappingValue() {
    if (this.scanner.checkToken(T.VALUE)) {
      const token = this.scanner.getToken();
      if (!this.scanner.checkToken(T.KEY, T.VALUE, T.BLOCK_END)) {
        this.states.push(this.parseBlockMappingKey);
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = this.parseBlockMappingKey;
      return this.processEmptyScalar(token.endMark);
    }
    this.state = this.parseBlockMappingKey;
    const token = this.scanner.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  // -- flow sequence ---------------------------------------------------
  parseFlowSequenceFirstEntry() {
    const token = this.scanner.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowSequenceEntry(true);
  }

  parseFlowSequenceEntry(first = false) {
    if (!this.scanner.checkToken(T.FLOW_SEQUENCE_END)) {
      if (!first) {
        if (this.scanner.checkToken(T.FLOW_ENTRY)) {
          this.scanner.getToken();
        } else {
          const token = this.scanner.peekToken();
          throw new ParserError('while parsing a flow sequence',
            this.marks[this.marks.length - 1],
            `expected ',' or ']', but got ${token.id}`, token.startMark);
        }
      }
      if (this.scanner.checkToken(T.KEY)) {
        const token = this.scanner.peekToken();
        const event = new MappingStartEvent(null, null, true, token.startMark,
          token.endMark, true);
        this.state = this.parseFlowSequenceEntryMappingKey;
        return event;
      }
      if (!this.scanner.checkToken(T.FLOW_SEQUENCE_END)) {
        this.states.push(this.parseFlowSequenceEntryWrapper);
        return this.parseFlowNode();
      }
    }
    const token = this.scanner.getToken();
    const event = new SequenceEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseFlowSequenceEntryWrapper() {
    return this.parseFlowSequenceEntry(false);
  }

  parseFlowSequenceEntryMappingKey() {
    const token = this.scanner.getToken();
    if (!this.scanner.checkToken(T.VALUE, T.FLOW_ENTRY, T.FLOW_SEQUENCE_END)) {
      this.states.push(this.parseFlowSequenceEntryMappingValue);
      return this.parseFlowNode();
    }
    this.state = this.parseFlowSequenceEntryMappingValue;
    return this.processEmptyScalar(token.endMark);
  }

  parseFlowSequenceEntryMappingValue() {
    if (this.scanner.checkToken(T.VALUE)) {
      const token = this.scanner.getToken();
      if (!this.scanner.checkToken(T.FLOW_ENTRY, T.FLOW_SEQUENCE_END)) {
        this.states.push(this.parseFlowSequenceEntryMappingEnd);
        return this.parseFlowNode();
      }
      this.state = this.parseFlowSequenceEntryMappingEnd;
      return this.processEmptyScalar(token.endMark);
    }
    this.state = this.parseFlowSequenceEntryMappingEnd;
    const token = this.scanner.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  parseFlowSequenceEntryMappingEnd() {
    this.state = this.parseFlowSequenceEntryWrapper;
    const token = this.scanner.peekToken();
    return new MappingEndEvent(token.startMark, token.startMark);
  }

  // -- flow mapping ----------------------------------------------------
  parseFlowMappingFirstKey() {
    const token = this.scanner.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowMappingKey(true);
  }

  parseFlowMappingKey(first = false) {
    if (!this.scanner.checkToken(T.FLOW_MAPPING_END)) {
      if (!first) {
        if (this.scanner.checkToken(T.FLOW_ENTRY)) {
          this.scanner.getToken();
        } else {
          const token = this.scanner.peekToken();
          throw new ParserError('while parsing a flow mapping',
            this.marks[this.marks.length - 1],
            `expected ',' or '}', but got ${token.id}`, token.startMark);
        }
      }
      if (this.scanner.checkToken(T.KEY)) {
        const token = this.scanner.getToken();
        if (!this.scanner.checkToken(T.VALUE, T.FLOW_ENTRY, T.FLOW_MAPPING_END)) {
          this.states.push(this.parseFlowMappingValue);
          return this.parseFlowNode();
        }
        this.state = this.parseFlowMappingValue;
        return this.processEmptyScalar(token.endMark);
      }
      if (!this.scanner.checkToken(T.FLOW_MAPPING_END)) {
        this.states.push(this.parseFlowMappingEmptyValue);
        return this.parseFlowNode();
      }
    }
    const token = this.scanner.getToken();
    const event = new MappingEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseFlowMappingKeyWrapper() {
    return this.parseFlowMappingKey(false);
  }

  parseFlowMappingValue() {
    if (this.scanner.checkToken(T.VALUE)) {
      const token = this.scanner.getToken();
      if (!this.scanner.checkToken(T.FLOW_ENTRY, T.FLOW_MAPPING_END)) {
        this.states.push(this.parseFlowMappingKeyWrapper);
        return this.parseFlowNode();
      }
      this.state = this.parseFlowMappingKeyWrapper;
      return this.processEmptyScalar(token.endMark);
    }
    this.state = this.parseFlowMappingKeyWrapper;
    const token = this.scanner.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  parseFlowMappingEmptyValue() {
    this.state = this.parseFlowMappingKeyWrapper;
    return this.processEmptyScalar(this.scanner.peekToken().startMark);
  }

  processEmptyScalar(mark) {
    return new ScalarEvent(null, null, [true, false], '', mark, mark);
  }
}

