// Resolver: decides the implicit tag of a plain scalar.
//
// PyYAML expresses these rules as regular expressions.  They are reimplemented
// here as explicit character scanners, preserving the same alternation order
// (bool, float, int, merge, null, timestamp, value) and the same anchoring.

import { toCodePoints, isDigit, isHexDigit } from './chars.mjs';

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

const BOOL_VALUES = new Set([
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
]);

const NULL_VALUES = new Set(['~', 'null', 'Null', 'NULL', '']);

function isDigitOrUnderscore(ch) {
  return ch !== undefined && (isDigit(ch) || ch === '_');
}

function isBinDigitOrUnderscore(ch) {
  return ch === '0' || ch === '1' || ch === '_';
}

function isOctDigitOrUnderscore(ch) {
  return ch !== undefined && ((ch >= '0' && ch <= '7') || ch === '_');
}

function isHexDigitOrUnderscore(ch) {
  return ch !== undefined && (isHexDigit(ch) || ch === '_');
}

/** Skips an optional leading '+'/'-'. */
function skipSign(c, i) {
  return (c[i] === '-' || c[i] === '+') ? i + 1 : i;
}

/** `[eE][-+][0-9]+` -- note the sign is mandatory in YAML 1.1. */
function matchExponent(c, i) {
  if (c[i] !== 'e' && c[i] !== 'E') return -1;
  let j = i + 1;
  if (c[j] !== '-' && c[j] !== '+') return -1;
  j += 1;
  if (!isDigit(c[j])) return -1;
  while (isDigit(c[j])) j += 1;
  return j;
}

/**
 * `(?::[0-5]?[0-9])+` followed by `tail`.  The optional `[0-5]` makes the
 * group ambiguous, so this explores both readings the way a backtracking
 * engine would.
 */
function matchSexagesimal(c, i, tail, first) {
  if (!first && tail(i)) return true;
  if (c[i] !== ':') return false;
  const p = i + 1;
  if (c[p] >= '0' && c[p] <= '5' && isDigit(c[p + 1])) {
    if (matchSexagesimal(c, p + 2, tail, false)) return true;
  }
  if (isDigit(c[p])) {
    if (matchSexagesimal(c, p + 1, tail, false)) return true;
  }
  return false;
}

function matchFloat(c) {
  const n = c.length;
  const atEnd = (i) => i === n;

  // [-+]? [0-9][0-9_]* \. [0-9_]* ([eE][-+][0-9]+)?
  {
    let i = skipSign(c, 0);
    if (isDigit(c[i])) {
      let j = i + 1;
      while (isDigitOrUnderscore(c[j])) j += 1;
      if (c[j] === '.') {
        j += 1;
        while (isDigitOrUnderscore(c[j])) j += 1;
        if (j === n) return true;
        const k = matchExponent(c, j);
        if (k === n) return true;
      }
    }
  }
  // \. [0-9_]+ ([eE][-+][0-9]+)?
  if (c[0] === '.') {
    let j = 1;
    if (isDigitOrUnderscore(c[j])) {
      while (isDigitOrUnderscore(c[j])) j += 1;
      if (j === n) return true;
      const k = matchExponent(c, j);
      if (k === n) return true;
    }
  }
  // [-+]? [0-9][0-9_]* (:[0-5]?[0-9])+ \. [0-9_]*
  {
    let i = skipSign(c, 0);
    if (isDigit(c[i])) {
      let j = i + 1;
      while (isDigitOrUnderscore(c[j])) j += 1;
      const tail = (p) => {
        if (c[p] !== '.') return false;
        let q = p + 1;
        while (isDigitOrUnderscore(c[q])) q += 1;
        return q === n;
      };
      if (matchSexagesimal(c, j, tail, true)) return true;
    }
  }
  // [-+]? \. (inf|Inf|INF)
  {
    const i = skipSign(c, 0);
    if (c[i] === '.') {
      const rest = c.slice(i + 1).join('');
      if (rest === 'inf' || rest === 'Inf' || rest === 'INF') return true;
    }
  }
  // \. (nan|NaN|NAN)
  if (c[0] === '.') {
    const rest = c.slice(1).join('');
    if (rest === 'nan' || rest === 'NaN' || rest === 'NAN') return true;
  }
  return false;
}

function matchInt(c) {
  const n = c.length;
  // [-+]? 0b [0-1_]+
  {
    const i = skipSign(c, 0);
    if (c[i] === '0' && c[i + 1] === 'b') {
      let j = i + 2;
      if (isBinDigitOrUnderscore(c[j])) {
        while (isBinDigitOrUnderscore(c[j])) j += 1;
        if (j === n) return true;
      }
    }
  }
  // [-+]? 0 [0-7_]+
  {
    const i = skipSign(c, 0);
    if (c[i] === '0') {
      let j = i + 1;
      if (isOctDigitOrUnderscore(c[j])) {
        while (isOctDigitOrUnderscore(c[j])) j += 1;
        if (j === n) return true;
      }
    }
  }
  // [-+]? (0 | [1-9][0-9_]*)
  {
    const i = skipSign(c, 0);
    if (c[i] === '0' && i + 1 === n) return true;
    if (c[i] >= '1' && c[i] <= '9') {
      let j = i + 1;
      while (isDigitOrUnderscore(c[j])) j += 1;
      if (j === n) return true;
    }
  }
  // [-+]? 0x [0-9a-fA-F_]+
  {
    const i = skipSign(c, 0);
    if (c[i] === '0' && c[i + 1] === 'x') {
      let j = i + 2;
      if (isHexDigitOrUnderscore(c[j])) {
        while (isHexDigitOrUnderscore(c[j])) j += 1;
        if (j === n) return true;
      }
    }
  }
  // [-+]? [1-9][0-9_]* (:[0-5]?[0-9])+
  {
    const i = skipSign(c, 0);
    if (c[i] >= '1' && c[i] <= '9') {
      let j = i + 1;
      while (isDigitOrUnderscore(c[j])) j += 1;
      if (matchSexagesimal(c, j, (p) => p === n, true)) return true;
    }
  }
  return false;
}

function digitsExactly(c, i, count) {
  for (let k = 0; k < count; k++) {
    if (!isDigit(c[i + k])) return -1;
  }
  return i + count;
}

/** One or two digits. */
function digits1or2(c, i) {
  if (!isDigit(c[i])) return -1;
  return isDigit(c[i + 1]) ? i + 2 : i + 1;
}

export function matchTimestamp(c) {
  const n = c.length;
  // YYYY-MM-DD
  {
    let i = digitsExactly(c, 0, 4);
    if (i > 0 && c[i] === '-') {
      i = digitsExactly(c, i + 1, 2);
      if (i > 0 && c[i] === '-') {
        i = digitsExactly(c, i + 1, 2);
        if (i === n) return true;
      }
    }
  }
  // YYYY-M?M-D?D ([Tt]|[ \t]+) H?H:MM:SS (\.[0-9]*)? ([ \t]* (Z|[-+]H?H(:MM)?))?
  {
    let i = digitsExactly(c, 0, 4);
    if (i < 0 || c[i] !== '-') return false;
    i = digits1or2(c, i + 1);
    if (i < 0 || c[i] !== '-') return false;
    i = digits1or2(c, i + 1);
    if (i < 0) return false;
    if (c[i] === 'T' || c[i] === 't') {
      i += 1;
    } else if (c[i] === ' ' || c[i] === '\t') {
      while (c[i] === ' ' || c[i] === '\t') i += 1;
    } else {
      return false;
    }
    i = digits1or2(c, i);
    if (i < 0 || c[i] !== ':') return false;
    i = digitsExactly(c, i + 1, 2);
    if (i < 0 || c[i] !== ':') return false;
    i = digitsExactly(c, i + 1, 2);
    if (i < 0) return false;
    if (c[i] === '.') {
      i += 1;
      while (isDigit(c[i])) i += 1;
    }
    if (i === n) return true;
    while (c[i] === ' ' || c[i] === '\t') i += 1;
