// Composer: events -> representation graph.  Port of PyYAML's composer.

import { ComposerError } from './errors.mjs';
import {
  StreamStartEvent, StreamEndEvent, AliasEvent, ScalarEvent,
  SequenceStartEvent, SequenceEndEvent, MappingStartEvent, MappingEndEvent,
} from './events.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';

export class Composer {
  constructor(parser, resolver) {
    this.parser = parser;
    this.resolver = resolver;
    this.anchors = new Map();
  }

  getSingleNode() {
    // Drop the STREAM-START event.
    this.parser.getEvent();
    let document = null;
    if (!this.parser.checkEvent(StreamEndEvent)) {
      document = this.composeDocument();
    }
    if (!this.parser.checkEvent(StreamEndEvent)) {
      const event = this.parser.getEvent();
      throw new ComposerError('expected a single document in the stream',
        document.startMark, 'but found another document', event.startMark);
    }
    this.parser.getEvent();
    return document;
  }

  composeDocument() {
    this.parser.getEvent(); // DOCUMENT-START
    const node = this.composeNode(null, null);
    this.parser.getEvent(); // DOCUMENT-END
    this.anchors = new Map();
    return node;
  }

  composeNode(parent, index) {
    if (this.parser.checkEvent(AliasEvent)) {
      const event = this.parser.getEvent();
      const anchor = event.anchor;
      if (!this.anchors.has(anchor)) {
        throw new ComposerError(null, null,
          `found undefined alias ${quote(anchor)}`, event.startMark);
      }
      return this.anchors.get(anchor);
    }
    const event = this.parser.peekEvent();
    const anchor = event.anchor;
    if (anchor !== null && this.anchors.has(anchor)) {
      throw new ComposerError(
        `found duplicate anchor ${quote(anchor)}; first occurrence`,
        this.anchors.get(anchor).startMark, 'second occurrence', event.startMark);
    }
    if (this.parser.checkEvent(ScalarEvent)) return this.composeScalarNode(anchor);
    if (this.parser.checkEvent(SequenceStartEvent)) return this.composeSequenceNode(anchor);
    if (this.parser.checkEvent(MappingStartEvent)) return this.composeMappingNode(anchor);
    return null;
  }

  composeScalarNode(anchor) {
    const event = this.parser.getEvent();
    let tag = event.tag;
    if (tag === null || tag === '!') {
      tag = this.resolver.resolve('scalar', event.value, event.implicit);
    }
    const node = new ScalarNode(tag, event.value, event.startMark, event.endMark,
      event.style);
    if (anchor !== null) this.anchors.set(anchor, node);
    return node;
  }

  composeSequenceNode(anchor) {
    const startEvent = this.parser.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = this.resolver.resolve('sequence', null, startEvent.implicit);
    }
    const node = new SequenceNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    let index = 0;
    while (!this.parser.checkEvent(SequenceEndEvent)) {
      node.value.push(this.composeNode(node, index));
      index += 1;
    }
    const endEvent = this.parser.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }

  composeMappingNode(anchor) {
    const startEvent = this.parser.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = this.resolver.resolve('mapping', null, startEvent.implicit);
    }
    const node = new MappingNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    while (!this.parser.checkEvent(MappingEndEvent)) {
      const itemKey = this.composeNode(node, null);
      const itemValue = this.composeNode(node, itemKey);
      node.value.push([itemKey, itemValue]);
    }
    const endEvent = this.parser.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }
}

function quote(s) {
  return `'${s}'`;
}

