      case 'tag:yaml.org,2002:null': return this.constructYamlNull;
      case 'tag:yaml.org,2002:bool': return this.constructYamlBool;
      case 'tag:yaml.org,2002:int': return this.constructYamlInt;
      case 'tag:yaml.org,2002:float': return this.constructYamlFloat;
      case 'tag:yaml.org,2002:binary': return this.constructYamlBinary;
      case 'tag:yaml.org,2002:timestamp': return this.constructYamlTimestamp;
      case 'tag:yaml.org,2002:omap': return this.constructYamlOmap;
      case 'tag:yaml.org,2002:pairs': return this.constructYamlPairs;
      case 'tag:yaml.org,2002:set': return this.constructYamlSet;
      case 'tag:yaml.org,2002:str': return this.constructYamlStr;
      case 'tag:yaml.org,2002:seq': return this.constructYamlSeq;
      case 'tag:yaml.org,2002:map': return this.constructYamlMap;
