// SafeConstructor: representation graph -> Python-like values.

import { ConstructorError } from './errors.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import { isDigit } from './chars.mjs';
import {
  PyDict, PySet, PyTuple, PyDate, PyDateTime, PyValueError,
} from './pytypes.mjs';

const BOOL_VALUES = new Map([
  ['yes', true], ['no', false],
  ['true', true], ['false', false],
  ['on', true], ['off', false],
]);

const B64_ALPHABET =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function base64Decode(text) {
  const values = [];
  for (const ch of text) {
    if (ch === '=') break;
    const v = B64_ALPHABET.indexOf(ch);
    if (v !== -1) values.push(v);
  }
  const rem = values.length % 4;
  if (rem === 1) {
    throw new Error(
      `Invalid base64-encoded string: number of data characters (${values.length}) cannot be 1 more than a multiple of 4`);
  }
  const full = values.length - rem;
  const out = [];
  for (let i = 0; i < full; i += 4) {
    const n = (values[i] << 18) | (values[i + 1] << 12) | (values[i + 2] << 6) | values[i + 3];
    out.push((n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff);
  }
  if (rem === 2) {
    out.push(((values[full] << 2) | (values[full + 1] >> 4)) & 0xff);
  } else if (rem === 3) {
    const n = (values[full] << 10) | (values[full + 1] << 4) | (values[full + 2] >> 2);
    out.push((n >> 8) & 0xff, n & 0xff);
  }
  return new Uint8Array(out);
}

/** Parses the timestamp shape accepted by PyYAML's construct_yaml_timestamp. */
function parseTimestamp(value) {
  const c = Array.from(value);
  let i = 0;
  const takeDigits = (min, max) => {
    let s = '';
    while (i < c.length && isDigit(c[i]) && s.length < max) {
      s += c[i];
      i += 1;
    }
    return s.length >= min ? s : null;
  };
  const year = takeDigits(4, 4);
  if (year === null || c[i] !== '-') return null;
  i += 1;
  const month = takeDigits(1, 2);
  if (month === null || c[i] !== '-') return null;
  i += 1;
  const day = takeDigits(1, 2);
  if (day === null) return null;
  if (i === c.length) {
    return { year: +year, month: +month, day: +day, dateOnly: true };
  }
  if (c[i] === 'T' || c[i] === 't') {
    i += 1;
  } else if (c[i] === ' ' || c[i] === '\t') {
    while (c[i] === ' ' || c[i] === '\t') i += 1;
  } else {
    return null;
  }
  const hour = takeDigits(1, 2);
  if (hour === null || c[i] !== ':') return null;
  i += 1;
  const minute = takeDigits(2, 2);
  if (minute === null || c[i] !== ':') return null;
  i += 1;
  const second = takeDigits(2, 2);
  if (second === null) return null;
  let fraction = '';
  if (c[i] === '.') {
    i += 1;
    while (i < c.length && isDigit(c[i])) {
      fraction += c[i];
      i += 1;
    }
  }
  let tzOffset = null;
  if (i < c.length) {
    while (c[i] === ' ' || c[i] === '\t') i += 1;
    if (c[i] === 'Z') {
      tzOffset = 0;
      i += 1;
    } else if (c[i] === '-' || c[i] === '+') {
      const sign = c[i] === '-' ? -1 : 1;
      i += 1;
      const tzHour = takeDigits(1, 2);
      if (tzHour === null) return null;
      let tzMinute = '0';
      if (c[i] === ':') {
        i += 1;
        tzMinute = takeDigits(2, 2);
        if (tzMinute === null) return null;
      }
      tzOffset = sign * (+tzHour * 60 + +tzMinute);
    } else {
      return null;
    }
  }
  if (i !== c.length) return null;
  let micro = 0;
  if (fraction) {
    let f = fraction.slice(0, 6);
    while (f.length < 6) f += '0';
    micro = +f;
  }
  return {
    year: +year, month: +month, day: +day, dateOnly: false,
    hour: +hour, minute: +minute, second: +second,
    microsecond: micro, tzOffset,
  };
}

