                subnode.startMark);
            }
            this.flattenMapping(subnode);
            submerge.push(subnode.value);
          }
          submerge.reverse();
          for (const value of submerge) merge.push(...value);
        } else {
          throw new ConstructorError('while constructing a mapping',
            node.startMark,
            `expected a mapping or list of mappings for merging, but found ${valueNode.id}`,
            valueNode.startMark);
        }
      } else if (keyNode.tag === 'tag:yaml.org,2002:value') {
        keyNode.tag = 'tag:yaml.org,2002:str';
        index += 1;
      } else {
        index += 1;
      }
    }
    if (merge.length) node.value = merge.concat(node.value);
  }

  // -- tag constructors ------------------------------------------------
  constructYamlNull(node) {
    this.constructScalar(node);
    return null;
  }

  constructYamlBool(node) {
    const value = this.constructScalar(node);
    return BOOL_VALUES.get(value.toLowerCase());
  }

  constructYamlInt(node) {
    let value = this.constructScalar(node).split('_').join('');
    let sign = 1n;
    if (value[0] === '-') sign = -1n;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '0') return 0n;
    if (value.startsWith('0b')) return sign * toBigInt('0b' + value.slice(2), value, 2);
    if (value.startsWith('0x')) return sign * toBigInt('0x' + value.slice(2), value, 16);
    if (value[0] === '0') return sign * toBigInt('0o' + value.slice(1), value, 8);
    if (value.indexOf(':') !== -1) {
      const digits = value.split(':').map((part) => toBigInt(part, part, 10));
      digits.reverse();
      let base = 1n;
      let total = 0n;
      for (const digit of digits) {
        total += digit * base;
        base *= 60n;
      }
      return sign * total;
    }
    return sign * toBigInt(value, value, 10);
  }

  constructYamlFloat(node) {
    let value = this.constructScalar(node).split('_').join('').toLowerCase();
    let sign = 1;
    if (value[0] === '-') sign = -1;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '.inf') return sign * Infinity;
    if (value === '.nan') return NaN;
    if (value.indexOf(':') !== -1) {
      const digits = value.split(':').map(toFloat);
      digits.reverse();
      let base = 1;
      let total = 0;
      for (const digit of digits) {
        total += digit * base;
        base *= 60;
      }
      return sign * total;
    }
    return sign * toFloat(value);
  }

  constructYamlBinary(node) {
    const value = this.constructScalar(node);
    for (const ch of value) {
      if (ch.codePointAt(0) > 0x7f) {
        throw new ConstructorError(null, null,
          `failed to convert base64 data into ascii: ${ch}`, node.startMark);
      }
    }
    try {
      return base64Decode(value);
    } catch (err) {
      throw new ConstructorError(null, null,
        `failed to decode base64 data: ${err.message}`, node.startMark);
    }
  }

  constructYamlTimestamp(node) {
    const value = this.constructScalar(node);
    const parts = parseTimestamp(value);
    if (parts === null) {
      throw new ConstructorError(null, null,
        `could not determine a timestamp from ${pyRepr(value)}`, node.startMark);
    }
    if (parts.dateOnly) return new PyDate(parts.year, parts.month, parts.day);
    return new PyDateTime(parts.year, parts.month, parts.day, parts.hour,
      parts.minute, parts.second, parts.microsecond, parts.tzOffset);
  }

  constructYamlStr(node) {
    return this.constructScalar(node);
  }

  constructYamlSeq(node) {
    const data = [];
    return {
      __twoPhase: true,
      value: data,
      finish: () => { data.push(...this.constructSequence(node)); },
    };
  }

  constructYamlMap(node) {
    const data = new PyDict();
    return {
      __twoPhase: true,
      value: data,
      finish: () => { data.update(this.constructMapping(node)); },
    };
  }

  constructYamlSet(node) {
    const data = new PySet();
    return {
      __twoPhase: true,
      value: data,
      finish: () => {
        const mapping = this.constructMapping(node);
        for (const key of mapping.keys()) data.add(key);
      },
    };
  }

  constructYamlOmap(node) {
    const omap = [];
    return {
      __twoPhase: true,
      value: omap,
      finish: () => {
        if (!(node instanceof SequenceNode)) {
          throw new ConstructorError('while constructing an ordered map',
            node.startMark, `expected a sequence, but found ${node.id}`,
            node.startMark);
        }
        for (const subnode of node.value) {
          if (!(subnode instanceof MappingNode)) {
            throw new ConstructorError('while constructing an ordered map',
              node.startMark, `expected a mapping of length 1, but found ${subnode.id}`,
              subnode.startMark);
          }
          if (subnode.value.length !== 1) {
            throw new ConstructorError('while constructing an ordered map',
              node.startMark,
              `expected a single mapping item, but found ${subnode.value.length} items`,
              subnode.startMark);
          }
          const [keyNode, valueNode] = subnode.value[0];
          omap.push(new PyTuple([this.constructObject(keyNode),
            this.constructObject(valueNode)]));
        }
      },
    };
  }

  constructYamlPairs(node) {
    const pairs = [];
    return {
      __twoPhase: true,
      value: pairs,
      finish: () => {
        if (!(node instanceof SequenceNode)) {
          throw new ConstructorError('while constructing pairs', node.startMark,
            `expected a sequence, but found ${node.id}`, node.startMark);
        }
        for (const subnode of node.value) {
          if (!(subnode instanceof MappingNode)) {
            throw new ConstructorError('while constructing pairs', node.startMark,
              `expected a mapping of length 1, but found ${subnode.id}`,
              subnode.startMark);
          }
          if (subnode.value.length !== 1) {
            throw new ConstructorError('while constructing pairs', node.startMark,
              `expected a single mapping item, but found ${subnode.value.length} items`,
              subnode.startMark);
          }
          const [keyNode, valueNode] = subnode.value[0];
          pairs.push(new PyTuple([this.constructObject(keyNode),
            this.constructObject(valueNode)]));
        }
      },
    };
  }
}

function isHashable(value) {
  return !(Array.isArray(value) || value instanceof PyDict || value instanceof PySet);
}

function toBigInt(text, original, base) {
  try {
    return BigInt(text);
  } catch (err) {
    throw new PyValueError(
      `invalid literal for int() with base ${base}: '${original}'`);
  }
}

function toFloat(text) {
  if (text === '') throw new PyValueError('could not convert string to float');
  const value = Number(text);
  if (Number.isNaN(value) && text !== 'nan') {
    throw new PyValueError(`could not convert string to float: '${text}'`);
  }
  return value;
}

function pyRepr(text) {
  if (text.indexOf("'") === -1) return `'${text}'`;
  return `"${text}"`;
}

