// Representer: Python-like values -> representation graph.
// Mirrors PyYAML's Representer (the non-safe one, which `yaml.dump` uses).

import { RepresenterError } from './errors.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import {
  PyDict, PySet, PyTuple, PyDate, PyDateTime, isBytes, objectId, floatRepr,
  sortedPairs,
} from './pytypes.mjs';

const B64_ALPHABET =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** Equivalent of Python's base64.encodebytes: 76-column lines, each with \n. */
function base64Encode(bytes) {
  let raw = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    const n = (b0 << 16) | (b1 << 8) | b2;
    raw += B64_ALPHABET[(n >> 18) & 63];
    raw += B64_ALPHABET[(n >> 12) & 63];
    raw += i + 1 < bytes.length ? B64_ALPHABET[(n >> 6) & 63] : '=';
    raw += i + 2 < bytes.length ? B64_ALPHABET[n & 63] : '=';
  }
  let out = '';
  for (let i = 0; i < raw.length; i += 76) out += raw.slice(i, i + 76) + '\n';
  return out;
}

export class Representer {
  constructor(serializer, options = {}) {
    this.serializer = serializer;
    this.defaultStyle = options.defaultStyle ?? null;
    this.defaultFlowStyle = options.defaultFlowStyle ?? false;
    this.sortKeys = options.sortKeys ?? true;
    this.representedObjects = new Map();
    this.aliasKey = null;
  }

  represent(data) {
    const node = this.representData(data);
    this.serializer.serialize(node);
    this.representedObjects = new Map();
    this.aliasKey = null;
  }

