// Serializer: representation graph -> events, assigning anchors on the way.

import { SerializerError } from './errors.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import { zfill } from './chars.mjs';
import {
  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
  MappingStartEvent, MappingEndEvent,
} from './events.mjs';

export class Serializer {
  constructor(emitter, resolver, options = {}) {
    this.emitter = emitter;
    this.resolver = resolver;
    this.useEncoding = options.encoding ?? null;
    this.useExplicitStart = options.explicitStart ?? null;
    this.useExplicitEnd = options.explicitEnd ?? null;
    this.useVersion = options.version ?? null;
    this.useTags = options.tags ?? null;
    this.serializedNodes = new Set();
    this.anchors = new Map();
    this.lastAnchorId = 0;
    this.closed = null;
  }

  open() {
    if (this.closed === null) {
      this.emitter.emit(new StreamStartEvent(null, null, this.useEncoding));
      this.closed = false;
    } else if (this.closed) {
      throw new SerializerError('serializer is closed');
    } else {
      throw new SerializerError('serializer is already opened');
    }
  }

  close() {
    if (this.closed === null) throw new SerializerError('serializer is not opened');
    if (!this.closed) {
      this.emitter.emit(new StreamEndEvent());
      this.closed = true;
    }
  }

  serialize(node) {
    if (this.closed === null) throw new SerializerError('serializer is not opened');
    if (this.closed) throw new SerializerError('serializer is closed');
    this.emitter.emit(new DocumentStartEvent(null, null, this.useExplicitStart,
      this.useVersion, this.useTags));
    this.anchorNode(node);
    this.serializeNode(node, null, null);
    this.emitter.emit(new DocumentEndEvent(null, null, this.useExplicitEnd));
    this.serializedNodes = new Set();
    this.anchors = new Map();
    this.lastAnchorId = 0;
  }

  anchorNode(node) {
    if (this.anchors.has(node)) {
      if (this.anchors.get(node) === null) {
        this.anchors.set(node, this.generateAnchor());
      }
    } else {
      this.anchors.set(node, null);
      if (node instanceof SequenceNode) {
        for (const item of node.value) this.anchorNode(item);
      } else if (node instanceof MappingNode) {
        for (const [key, value] of node.value) {
          this.anchorNode(key);
          this.anchorNode(value);
        }
      }
    }
  }

  generateAnchor() {
    this.lastAnchorId += 1;
    return 'id' + zfill(this.lastAnchorId, 3);
  }

  serializeNode(node, parent, index) {
    const alias = this.anchors.get(node);
    if (this.serializedNodes.has(node)) {
      this.emitter.emit(new AliasEvent(alias, null, null));
      return;
    }
    this.serializedNodes.add(node);
    if (node instanceof ScalarNode) {
      const detectedTag = this.resolver.resolve('scalar', node.value, [true, false]);
      const defaultTag = this.resolver.resolve('scalar', node.value, [false, true]);
      const implicit = [node.tag === detectedTag, node.tag === defaultTag];
      this.emitter.emit(new ScalarEvent(alias, node.tag, implicit, node.value,
        null, null, node.style));
    } else if (node instanceof SequenceNode) {
      const implicit = node.tag === this.resolver.resolve('sequence', node.value, true);
      this.emitter.emit(new SequenceStartEvent(alias, node.tag, implicit, null,
        null, node.flowStyle));
      let i = 0;
      for (const item of node.value) {
        this.serializeNode(item, node, i);
        i += 1;
      }
      this.emitter.emit(new SequenceEndEvent());
    } else if (node instanceof MappingNode) {
      const implicit = node.tag === this.resolver.resolve('mapping', node.value, true);
      this.emitter.emit(new MappingStartEvent(alias, node.tag, implicit, null,
        null, node.flowStyle));
      for (const [key, value] of node.value) {
        this.serializeNode(key, node, null);
        this.serializeNode(value, node, null);
      }
      this.emitter.emit(new MappingEndEvent());
    }
  }
}

