// Public API: the `yaml.safe_load` / `yaml.dump` pair used by the program.

import { Reader } from './reader.mjs';
import { Scanner } from './scanner.mjs';
import { Parser } from './parser.mjs';
import { Resolver } from './resolver.mjs';
import { Composer } from './composer.mjs';
import { SafeConstructor } from './constructor.mjs';
import { Representer } from './representer.mjs';
import { Serializer } from './serializer.mjs';
import { Emitter } from './emitter.mjs';

/** yaml.safe_load(stream) */
export function safeLoad(text) {
  const reader = new Reader(text);
  const scanner = new Scanner(reader);
  const parser = new Parser(scanner);
  const resolver = new Resolver();
  const composer = new Composer(parser, resolver);
  const constructor = new SafeConstructor(composer);
  return constructor.getSingleData();
}

/**
 * yaml.dump(data, **options)
 *
 * Defaults match PyYAML's: Dumper, sorted keys, width 80, indent 2,
 * allow_unicode=False.
 */
export function dump(data, options = {}) {
  const emitter = new Emitter(options);
  const resolver = new Resolver();
  const serializer = new Serializer(emitter, resolver, options);
  const representer = new Representer(serializer, options);
  serializer.open();
  representer.represent(data);
  serializer.close();
  return emitter.getValue();
}

