function errorName(err) {
  switch (err.name) {
    case 'ScannerError': return 'yaml.scanner.ScannerError';
    case 'ParserError': return 'yaml.parser.ParserError';
    case 'ComposerError': return 'yaml.composer.ComposerError';
    case 'ConstructorError': return 'yaml.constructor.ConstructorError';
    case 'ReaderError': return 'yaml.reader.ReaderError';
    case 'EmitterError': return 'yaml.emitter.EmitterError';
    case 'SerializerError': return 'yaml.serializer.SerializerError';
    case 'RepresenterError': return 'yaml.representer.RepresenterError';
    case 'TypeError': return 'TypeError';
    case 'ValueError': return 'ValueError';
    default: return err.name || 'Exception';
  }
}

/** Renders an uncaught exception the way CPython's default handler does. */
function formatTraceback(err) {
  const detail = err instanceof MarkedYAMLError || err instanceof YAMLError
    ? err.toString() : (err.message ?? String(err));
  return 'Traceback (most recent call last):\n' +
    '  File "test4.py", line 8, in <module>\n' +
    '    result = yaml.dump(yaml.safe_load(args.a), default_flow_style=False)' +
    '  # 块样式\n' +
    `${errorName(err)}: ${detail}\n`;
}

function main(argv) {
  const parser = new ArgumentParser(basename(argv[1] ?? 'test4.mjs'));
  let args;
  try {
    args = parser.parseArgs(argv.slice(2));
  } catch (err) {
    if (err instanceof ExitProgram) {
      if (err.stdout) process.stdout.write(err.stdout);
      if (err.stderr) process.stderr.write(err.stderr);
      return err.status;
    }
    throw err;
  }

  let result;
  try {
    result = dump(safeLoad(args.a), { defaultFlowStyle: false });
  } catch (err) {
    process.stderr.write(formatTraceback(err));
    return 1;
  }

  process.stdout.write(result + '\n');
  return 0;
}

process.exitCode = main(process.argv);

